def detect_frameworks(self, file_path: str) -> List[str]:
    """Detecta frameworks usados en un archivo basado en su contenido."""
    frameworks = []
    content = self._read_file_content(file_path)
    if not content:
        return frameworks

    extension = Path(file_path).suffix.lower()

    # Detectar frameworks según la extensión del archivo
    if extension in {'.py', '.pyx', '.pyw'}:
        frameworks.extend(self._detect_python_frameworks(content))
    elif extension in {'.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs'}:
        frameworks.extend(self._detect_js_ts_frameworks(content))
    elif extension in {'.java', '.kt', '.kts'}:
        frameworks.extend(self._detect_java_kotlin_frameworks(content))
    elif extension in {'.go'}:
        frameworks.extend(self._detect_go_frameworks(content))
    elif extension in {'.rs'}:
        frameworks.extend(self._detect_rust_frameworks(content))
    elif extension in {'.rb', '.erb', '.rake'}:
        frameworks.extend(self._detect_ruby_frameworks(content))
    elif extension in {'.php', '.phtml', '.php3', '.php4', '.php5', '.php7', '.phps'}:
        frameworks.extend(self._detect_php_frameworks(content))
    elif extension in {'.cs', '.csx'}:
        frameworks.extend(self._detect_csharp_frameworks(content))
    elif extension in {'.ex', '.exs'}:
        frameworks.extend(self._detect_elixir_frameworks(content))

    return list(set(frameworks))  # Eliminar duplicados

